{"implementation":"def solve(case):
    segments = case["segments"]
    allocations = [segment["minimum"] for segment in segments]
    capacities = [segment["capacity"] for segment in segments]
    importances = [segment["importance"] for segment in segments]

    remaining = max(0, case["budget"] - sum(allocations))
    remaining = min(remaining, sum(capacities[i] - allocations[i] for i in range(len(segments))))

    while remaining > 0:
        active = [i for i in range(len(segments)) if allocations[i] < capacities[i]]
        if not active:
            break

        positive = [i for i in active if importances[i] > 0]
        weighted = positive if positive else active
        weights = {i: (importances[i] if positive else 1) for i in weighted}
        weight_sum = sum(weights.values())
        before = remaining
        remainders = []

        for i in weighted:
            numerator = before * weights[i]
            grant = min(capacities[i] - allocations[i], numerator // weight_sum)
            allocations[i] += grant
            remaining -= grant
            if allocations[i] < capacities[i]:
                remainders.append((numerator % weight_sum, i))

        if remaining == 0:
            break

        if remaining < len(remainders) + 1:
            remainders.sort(key=lambda item: (-item[0], item[1]))
            for _, i in remainders:
                if remaining == 0:
                    break
                allocations[i] += 1
                remaining -= 1
        elif remaining == before:
            for i in weighted:
                if remaining == 0:
                    break
                if allocations[i] < capacities[i]:
                    allocations[i] += 1
                    remaining -= 1

    by_name = {segment["name"]: allocations[i] for i, segment in enumerate(segments)}
    return {"allocations": allocations, "by_name": by_name, "total": sum(allocations)}"}
